"""Generate/check the UTF-8 Overlay catalog; validate printf argument contracts."""
import argparse
import json
import pathlib
import re

root = pathlib.Path(__file__).resolve().parents[1]
parser = argparse.ArgumentParser()
parser.add_argument('--check', action='store_true')
args = parser.parse_args()
catalog = json.loads((root / 'tools/overlay_zh-CN.json').read_text(encoding='utf-8'))
specifiers = re.compile(r'%(?:[-+ #0]*\d*(?:\.\d+)?(?:ll|l|z)?[sdiufgxX])')
lines = ['#pragma once', '#include <string>', '#include <unordered_map>',
         '// Generated by tools/generate_overlay_translations.py; edit tools/overlay_zh-CN.json.',
         'namespace OverlayI18n {', 'inline const std::unordered_map<std::string, std::string>& Catalog() {',
         '    static const std::unordered_map<std::string, std::string> catalog{']
for en, zh in catalog.items():
    if specifiers.findall(en) != specifiers.findall(zh):
        raise SystemExit(f'Printf arguments differ: {en!r} -> {zh!r}')
    lines.append('        {' + json.dumps(en, ensure_ascii=False) + ', u8' + json.dumps(zh, ensure_ascii=False) + '},')
lines += ['    };', '    return catalog;', '}', '}']
content = '\n'.join(lines) + '\n'
target = root / 'sunone_aimbot_2/overlay/i18n_catalog.h'
if args.check:
    if target.read_text(encoding='utf-8') != content:
        raise SystemExit('Generated catalog is stale. Run tools/generate_overlay_translations.py.')
    print(f'{len(catalog)} translations: format arguments and generated header verified')
else:
    target.write_text(content, encoding='utf-8')
    print(f'Generated {len(catalog)} translations')
